import pytest

from youtube_dl.extractor.fourtube import FourTubeBaseIE


def test_extract_formats_downloads_tokens_and_returns_sorted_formats(monkeypatch):
    calls = []

    def fake_download_json(self, token_url, video_id, data=None, headers=None):
        calls.append((token_url, video_id, data, headers))
        return {
            '360': {'token': 'https://cdn.example/360.mp4'},
            '720': {'token': 'https://cdn.example/720.mp4'},
        }

    monkeypatch.setattr(FourTubeBaseIE, '_download_json', fake_download_json)

    extractor = FourTubeBaseIE()
    formats = extractor._extract_formats(
        'https://www.example.com/videos/example',
        'video-id',
        'media-id',
        ['720', '360'],
    )

    assert calls == [(
        'https://%s/%s/desktop/720+360' % (
            extractor._TKN_HOST, 'media-id'),
        'video-id',
        b'',
        {
            'Origin': 'https://www.example.com',
            'Referer': 'https://www.example.com/videos/example',
        },
    )]
    assert formats == [
        {
            'url': 'https://cdn.example/360.mp4',
            'format_id': '360p',
            'resolution': '360p',
            'quality': 360,
        },
        {
            'url': 'https://cdn.example/720.mp4',
            'format_id': '720p',
            'resolution': '720p',
            'quality': 720,
        },
    ]


def test_extract_formats_handles_multiple_sources_and_preserves_token_mapping(
        monkeypatch):
    requested = []

    def fake_download_json(self, token_url, video_id, data=None, headers=None):
        requested.append({
            'url': token_url,
            'video_id': video_id,
            'data': data,
            'headers': headers,
        })
        return {
            '144': {'token': 'token-144'},
            '1080': {'token': 'token-1080'},
            '480': {'token': 'token-480'},
        }

    monkeypatch.setattr(FourTubeBaseIE, '_download_json', fake_download_json)

    extractor = FourTubeBaseIE()
    formats = extractor._extract_formats(
        'http://media.example.test/watch?id=123',
        '123',
        'abc',
        ['1080', '144', '480'],
    )

    assert requested == [{
        'url': 'https://%s/abc/desktop/1080+144+480' % extractor._TKN_HOST,
        'video_id': '123',
        'data': b'',
        'headers': {
            'Origin': 'http://media.example.test',
            'Referer': 'http://media.example.test/watch?id=123',
        },
    }]
    assert [item['format_id'] for item in formats] == ['144p', '480p', '1080p']
    assert [item['quality'] for item in formats] == [144, 480, 1080]
    assert [item['url'] for item in formats] == [
        'token-144',
        'token-480',
        'token-1080',
    ]
